import{c as i,S as r,j as l,m as a}from"./chunks/framework.8aa1YH_s.js";const h=JSON.parse('{"title":"Türk Dil Bilgisi Serisi - 8: Şekil Bilgisi (Morfoloji) - Kelime Yapısı, Kökler ve Gövdeler","description":"","frontmatter":{},"headers":[],"relativePath":"8 Şekil Bilgisi (Morfoloji) - Kelime Yapısı, Kökler ve Gövdeler.md","filePath":"8 Şekil Bilgisi (Morfoloji) - Kelime Yapısı, Kökler ve Gövdeler.md"}'),k={name:"8 Şekil Bilgisi (Morfoloji) - Kelime Yapısı, Kökler ve Gövdeler.md"};function n(m,e,o,s,t,d){return r(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="turk-dil-bilgisi-serisi-8-sekil-bilgisi-morfoloji-kelime-yapısı-kokler-ve-govdeler" tabindex="-1">Türk Dil Bilgisi Serisi - 8: Şekil Bilgisi (Morfoloji) - Kelime Yapısı, Kökler ve Gövdeler <a class="header-anchor" href="#turk-dil-bilgisi-serisi-8-sekil-bilgisi-morfoloji-kelime-yapısı-kokler-ve-govdeler" aria-label="Permalink to “Türk Dil Bilgisi Serisi - 8: Şekil Bilgisi (Morfoloji) - Kelime Yapısı, Kökler ve Gövdeler”">​</a></h1><p>Ses bilgisini (fonetik) arkamızda bırakarak Türkçenin asıl yapısal mekanizmasını inceleyeceğimiz <strong>Şekil Bilgisi (Morfoloji)</strong> bölümüne adım atıyoruz. Prof. Dr. Muharrem Ergin&#39;e göre şekil bilgisi; kelimelerin yapısını, köklerini, eklerini ve bu eklerin kelimelere nasıl can verip yeni kavramlar türettiğini inceleyen bilim dalıdır.</p><p>Türkçe, yapı bakımından eklemeli (bitişken) bir dil olduğu için, şekil bilgisinin kuralları adeta bir lego parçalarının birleşmesi gibi kusursuz bir matematik üzerine kuruludur.</p><hr><h2 id="_1-kok-nedir" tabindex="-1">1. Kök Nedir? <a class="header-anchor" href="#_1-kok-nedir" aria-label="Permalink to “1. Kök Nedir?”">​</a></h2><p>Bir kelimenin üzerinde anlamlı en küçük yapı taşına inildiğinde, artık daha fazla bölünemeyen ve kelimenin bütünüyle doğrudan anlam bağı taşıyan ilk parçasına <strong>kök</strong> denir.</p><p>Muharrem Ergin sistematiğinde köklerin en büyük özelliği şudur: <strong>Türkçede kökler sabittir, ek alırken asla değişime uğramazlar.</strong> (Arapça gibi bükümlü dillerin aksine).</p><p><em>Örnek:</em> <em>Gözlükçülük</em> kelimesini parçalayalım:</p><ul><li>Göz-lük-çü-lük $$\\rightarrow$$ En küçük anlamlı parça: <strong>Göz</strong> (Kök).</li></ul><hr><h2 id="_2-turkcede-kok-turleri" tabindex="-1">2. Türkçede Kök Türleri <a class="header-anchor" href="#_2-turkcede-kok-turleri" aria-label="Permalink to “2. Türkçede Kök Türleri”">​</a></h2><p>Muharrem Ergin, Türkçedeki tüm kelime köklerini tabiatları ve işlevleri bakımından <strong>iki ana gruba</strong> ayırır. Türkçede bu iki grubun dışında üçüncü bir kök türü yoktur.</p><h3 id="a-isim-kokleri" tabindex="-1">A) İsim Kökleri <a class="header-anchor" href="#a-isim-kokleri" aria-label="Permalink to “A) İsim Kökleri”">​</a></h3><p>Kainattaki canlı veya cansız varlıkları, kavramları, duygu ve düşünceleri karşılayan, onlara isim olan köklerdir. İsim kökleri iş, oluş veya hareket bildirmezler. Bunları ayırt etmenin en kolay yolu, sonlarına <code>-mak / -mek</code> master ekini <strong>alamıyor</strong> olmalarıdır.</p><ul><li><em>Örnekler:</em> <em>Su, taş, göz, yol, baş, ev, ağaç, kan, iç, iyi, gök...</em></li></ul><h3 id="b-fiil-kokleri-hareket-kokleri" tabindex="-1">B) Fiil Kökleri (Hareket Kökleri) <a class="header-anchor" href="#b-fiil-kokleri-hareket-kokleri" aria-label="Permalink to “B) Fiil Kökleri (Hareket Kökleri)”">​</a></h3><p>Kainattaki işleri, oluşları, hareketleri ve kılışları karşılayan köklerdir. Bünyelerinde mutlaka bir zaman ve hareket barındırırlar. Sonlarına <code>-mak / -mek</code> master ekini <strong>alabilirler</strong>.</p><ul><li><em>Örnekler:</em> <em>Gel-(mek), git-(mek), gör-(mek), yaz-(mek), al-(mak), koş-(mak), sev-(mek)...</em></li></ul><blockquote><p><strong>⚠️ Önemli Not (Ortak Kök / Sesteş Kök):</strong> &gt; Türkçede bazı kökler vardır ki hem isim hem de fiil olarak kullanılabilirler. Bunlar aralarındaki anlam bağına göre ikiye ayrılır:</p><ol><li><strong>Sesteş (Eş Sesli) Kökler:</strong> Aralarında hiçbir anlam bağı yoktur. Sadece ses benzerliğidir. (Örn: <em>Yüz</em> (sayı/çehre) - <em>Yüz-</em> (yüzmek); <em>Gül</em> (çiçek) - <em>Gül-</em> (gülmek)).</li><li><strong>Kökteş (İkili) Kökler:</strong> İsim ve fiil hali arasında çok güçlü bir anlam bağı vardır. (Örn: <em>Boya</em> (renk veren madde) - <em>Boya-</em> (boyama işi); <em>Güreş</em> (spor) - <em>Güreş-</em> (güreşmek)).</li></ol></blockquote><hr><h2 id="_3-govde-nedir" tabindex="-1">3. Gövde Nedir? <a class="header-anchor" href="#_3-govde-nedir" aria-label="Permalink to “3. Gövde Nedir?”">​</a></h2><p>Kelimelerin sadece kök halleri dildeki her ihtiyacı karşılamaz. Bir kelime kökünün üzerine en az bir tane <strong>Yapım Eki</strong> gelmesiyle oluşan yeni ve türetilmiş kelime biçimine <strong>gövde</strong> adı verilir. Gövdeler artık yeni birer kavramı karşılarlar.</p><ul><li><em>Formül:</em> <code>Kök + Yapım Eki = Gövde</code></li></ul><h3 id="govde-turleri" tabindex="-1">Gövde Türleri: <a class="header-anchor" href="#govde-turleri" aria-label="Permalink to “Gövde Türleri:”">​</a></h3><p>Köklerin türüne ve aldıkları eklere göre gövdeler de ikiye ayrılır:</p><ol><li><strong>İsim Gövdeleri:</strong> Son hali isim olan yapılardır. <ul><li><em>Ev</em> (İsim Kökü) + <em>-li</em> (Yapım Eki) $$\\rightarrow$$ <strong>Evli</strong> (İsim Gövdesi)</li><li><em>Göz</em> (İsim Kökü) + <em>-lük</em> (Yapım Eki) $$\\rightarrow$$ <strong>Gözlük</strong> (İsim Gövdesi)</li><li><em>Yaz-</em> (Fiil Kökü) + <em>-gıl</em> / <em>-gı</em> (Yapım Eki) $$\\rightarrow$$ <strong>Yazı</strong> (İsim Gövdesi)</li></ul></li><li><strong>Fiil Gövdeleri:</strong> Son hali bir eylem, hareket bildiren yapılardır. <ul><li><em>Göz</em> (İsim Kökü) + <em>-le-</em> (Yapım Eki) $$\\rightarrow$$ <strong>Gözle-mek</strong> (Fiil Gövdesi)</li><li><em>Su</em> (İsim Kökü) + <em>-la-</em> (Yapım Eki) $$\\rightarrow$$ <strong>Sula-mak</strong> (Fiil Gövdesi)</li><li><em>Gör-</em> (Fiil Kökü) + <em>-üş-</em> (Yapım Eki) $$\\rightarrow$$ <strong>Görüş-mek</strong> (Fiil Gövdesi)</li></ul></li></ol><hr><h2 id="ozet" tabindex="-1">Özet <a class="header-anchor" href="#ozet" aria-label="Permalink to “Özet”">​</a></h2><p>Prof. Dr. Muharrem Ergin&#39;in sistematiğinde Türkçenin kelime dünyası <strong>İsimler</strong> ve <strong>Fiiller</strong> olmak üzere iki temel nehir üzerinden akar. Kökler saf ve değişmez bir şekilde bu nehirlerin kaynağını oluştururken; yapım ekleri ise bu kaynaklardan yepyeni gövdeler, yani yeni anlam nehirleri türetir.</p><p>Şekil bilgisinin bu ilk adımını tamamladık aslanım!</p><p>Serimizin 9. bölümünde, kök ve gövdelere can veren, onları cümle içinde işlevsel kılan muazzam yapılara geçiyoruz: <strong>&quot;Ekler ve Yapım Ekleri (Kelimeden Kelime Türetme)&quot;</strong>.</p><p>Sayfayı çevir, tam gaz ileri!</p>',32)])])}const b=i(k,[["render",n]]);export{h as __pageData,b as default};
